def avg(nums):
    if not nums:
        return None
    return sum(nums) / len(nums)
思路：内置 sum + 空列表防空再除。注意除零与浮点语义。

class QueueByStack:
    def __init__(self):
        self.in_st = []
        self.out_st = []
    def push(self, x):
        self.in_st.append(x)
    def pop(self):
        self._move()
        return self.out_st.pop()
    def _move(self):
        if not self.out_st:
            while self.in_st:
                self.out_st.append(self.in_st.pop())
思路：两个栈，出队时把入栈倒到出栈。均摊O(1)。

def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        swapped = False
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
                swapped = True
        if not swapped:
            break
    return arr
思路：相邻两两比较交换，每轮把最大沉到底，可提前退出。复杂度O(n²)。

def is_prime(n):
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i*i <= n:
        if n % i == 0 or n % (i+2) == 0:
            return False
        i += 6
    return True
思路：排除2、3倍数，只测形如6k±1的因数。复杂度O(√n)。

def binary_search(arr, target):
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1
思路：每次缩小一半。复杂度O(log n)。

def is_balanced(s):
    stack = []
    pairs = {')': '(', ']': '['}
    for c in s:
        if c in '([':
            stack.append(c)
        elif c in ')]':
            if not stack or stack.pop() != pairs[c]:
                return False
    return not stack
思路：用栈，遇到右括号检查栈顶。复杂度O(n)。

def merge_sorted(a, b):
    i = j = 0
    out = []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            out.append(a[i]); i += 1
        else:
            out.append(b[j]); j += 1
    out.extend(a[i:])
    out.extend(b[j:])
    return out
思路：双指针两两比较。复杂度O(m+n)。

def second_largest(lst):
    first = second = float('-inf')
    for x in lst:
        if x > first:
            second, first = first, x
        elif x > second and x != first:
            second = x
    return second if second != float('-inf') else None
思路：一趟找最大和第二大。复杂度O(n)。

def majority(nums):
    cand = None
    count = 0
    for x in nums:
        if count == 0:
            cand = x
            count = 1
        elif x == cand:
            count += 1
        else:
            count -= 1
    return cand
思路：摩尔投票法。复杂度O(n)，空间O(1)。

def has_cycle(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            return True
    return False
思路：快慢指针，快指针追上慢即存在环。复杂度O(n)。

from collections import Counter

def first_unique(s):
    cnt = Counter(s)
    for i, c in enumerate(s):
        if cnt[c] == 1:
            return i
    return -1
思路：先统计频次，再遍历找第一个频次为1的。复杂度O(n)。

def unique_keep_order(lst):
    seen = set()
    out = []
    for x in lst:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out
思路：用set记录已见，保持原顺序。复杂度O(n)。

from collections import defaultdict

def group_by_len(words):
    d = defaultdict(list)
    for w in words.split():
        d[len(w)].append(w)
    return dict(d)
思路：defaultdict按长度分组。复杂度O(n)。

def fib(n):
    if n < 0:
        raise ValueError('n must >= 0')
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a
思路：只用两个变量滚动，迭代n次。复杂度O(n)，空间O(1)。

def find_sub(s1, s2):
    n, m = len(s1), len(s2)
    for i in range(n - m + 1):
        if s1[i:i+m] == s2:
            return i
    return -1
思路：朴素滑动窗口。复杂度O(nm)。大规模可用KMP。

from collections import Counter

def word_freq(sentence):
    words = sentence.split()
    return dict(Counter(words))
思路：split按空白分词，Counter统计频次，转dict返回。复杂度O(n)，n为单词数。

from collections import Counter

def most_common(lst):
    if not lst:
        return None
    return Counter(lst).most_common(1)[0][0]
思路：Counter统计后取最高频。复杂度O(n)。

def factorial(n):
    if n < 0:
        raise ValueError('cannot be negative')
    r = 1
    for i in range(2, n+1):
        r *= i
    return r
思路：迭代累乘。复杂度O(n)。

def is_perfect_square(n):
    if n < 0:
        return False
    r = int(n**0.5)
    return r*r == n or (r+1)*(r+1) == n
思路：取平方根整数部分，检查两侧是否恰为n。复杂度O(1)。

def bin_to_int(s):
    val = 0
    for c in s:
        val = val * 2 + (1 if c == '1' else 0)
    return val
思路：逐位累加。或直接用 int(s, 2)。复杂度O(n)。

def reverse_int(n):
    sign = -1 if n < 0 else 1
    s = str(abs(n))[::-1]
    return sign * int(s)
思路：取绝对值转字符串反转再还原符号。复杂度O(len(str))。

def reverse_str(s):
    res = ''
    for c in s:
        res = c + res
    return res
思路：每次把字符放前面。复杂度O(n²)因字符串不可变拼接。更优可用列表或s[::-1]。

import re

def camel_to_snake(name):
    return re.sub(r'(?<!^)(?=[A-Z])', '_', name).lower()
思路：用正则在大写字母前插下划线，再转小写。复杂度O(n)。

def gcd(a, b):
    while b:
        a, b = b, a % b
    return abs(a)
思路：辗转相除，a,b不断替换为b和a%b，直到b为0。复杂度O(log min(a,b))。

def sort_by_value(d):
    return [k for k, v in sorted(d.items(), key=lambda x: x[1])]
思路：按值排序键值对，取出键。复杂度O(n log n)。

def evens_sorted(nums):
    return sorted(x for x in nums if x % 2 == 0)
思路：生成器筛偶数，sorted升序。复杂度O(n log n)。

def is_palindrome(s):
    return s == s[::-1]
思路：与反转比较。若忽略大小写和空格可先s = s.lower().replace(' ', '')。复杂度O(n)。

def is_anagram(a, b):
    return sorted(a) == sorted(b)
或用Counter更高效。思路：排序后比较（或用频次字典）。复杂度O(n log n)。

def count_vowels(s):
    return sum(1 for c in s.lower() if c in 'aeiou')
思路：小写后判定。复杂度O(n)。

def sum_squares(n):
    return sum(i*i for i in range(1, n+1))
或用公式 n(n+1)(2n+1)/6。复杂度O(n)。

def rotate_90(m):
    return [list(row) for row in zip(*m[::-1])]
思路：先反转行序再转置。复杂度O(n²)。

def urlify(s):
    return s.replace(' ', '%20')
思路：replace即可。复杂度O(n)。

import time, functools
def timed(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        try:
            return func(*args, **kwargs)
        finally:
            cost = (time.perf_counter() - start) * 1000
            print(f"{func.__name__} 耗时 {cost:.3f} ms")
    return wrapper
用 perf_counter（精度高）、finally 保证即使报错也计时、wraps 保留原函数元数据。

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True
思路：1 和 0 非质数；2、3 是；偶数或 3 的倍数直接排除；其余只需检查形如 6k±1 的因子且到平方根即可，复杂度 O(sqrt(n))，比逐个整除快得多。

def quicksort(a):
    if len(a) <= 1:
        return a
    pivot = a[len(a) // 2]
    left = [x for x in a if x < pivot]
    mid = [x for x in a if x == pivot]
    right = [x for x in a if x > pivot]
    return quicksort(left) + mid + quicksort(right)
平均时间复杂度 O(n log n)，最坏（已排序且枢轴选得差）O(n²)，空间平均 O(log n)。此处取中位元素为枢轴，能规避常见的已排序退化。

def binary_search(arr, target):
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1
每次排除一半，前提是数组已升序，复杂度 O(log n)。边界用 lo<=hi，目标在左右淘汰中收敛。

def merge(a, b):
    res, i, j = [], 0, 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            res.append(a[i]); i += 1
        else:
            res.append(b[j]); j += 1
    res.extend(a[i:])
    res.extend(b[j:])
    return res
双指针归并：每次取两指针较小的，剩余部分一次性接上，O(m+n)。这就是归并排序的合并步骤。

class Singleton:
    _instance = None
    def __new__(cls, *args, **kwargs):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance
适用：配置管理器、日志、线程池等全局唯一对象。注意 Python 中多线程下需加锁保证线程安全；也可用模块级变量方案规避。

def count_lines(in_path, out_path):
    with open(in_path, encoding='utf-8') as f, open(out_path, 'w', encoding='utf-8') as g:
        for line in f:
            g.write(f"{len(line)}")
这样逐行处理，内存占用与文件大小无关。要点：用 with 保证资源释放，指定 encoding 避免中文乱码。

def fib(n):
    a, b = 0, 1
    for _ in range(n):
        yield a
        a, b = b, a + b
for x in fib(8):
    print(x)  # 0 1 1 2 3 5 8 13
生成器用 yield 惰性求值，不一次性在内存里建整个列表，适合大 n。状态在 a,b 之间滚动推进。

def reverse_str(s):
    result = []
    for i in range(len(s) - 1, -1, -1):
        result.append(s[i])
    return ''.join(result)
时间复杂度 O(n)、空间复杂度 O(n)。逐字符反向收集到列表再拼接，避免字符串不可变导致的 O(n²) 拼接开销。

def word_count(text):
    from collections import Counter
    return dict(Counter(text.split()))
text.split() 按空白切词，Counter 直接在内部构建频次字典。若需忽略大小写可先 .lower()。复杂度 O(n)。

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a
用欧几里得算法：gcd(a,b) = gcd(b, a mod b)，直到 b 为 0。复杂度 O(log min(a,b))，比逐数试除快得多。
